#pragma once

// Keyboard family button icons. With the Keyboard family active, the shared
// A.dds prompt image shows the Xelu Light keycap of the first key bound to
// keybind_a. The art ships as one 64x64 DDS per SDK key name, generated by
// scripts/build_keyboard_icons.py.

#include <cstddef>
#include <cstdint>
#include <filesystem>
#include <memory>
#include <optional>
#include <span>
#include <string_view>
#include <vector>

namespace rerevved::keyboard_icons
{

inline constexpr std::string_view kGuestFileName = "A.dds";
inline constexpr uint32_t         kIconDdsSize   = 16512u;

using Payload = std::shared_ptr<const std::vector<uint8_t>>;

// SDK key names that have shipped art, matched case-sensitively like the SDK.
std::span<const std::string_view> ShippedKeys() noexcept;

// First comma-separated alternative of a keybind, trimmed of outer spaces, when
// it is a single key with shipped art. A chord ("Shift+Space"), an empty
// alternative and an unknown or art-less key give nullopt; a later
// alternative is never used.
std::optional<std::string_view> PrimaryKey(std::string_view binding) noexcept;

// Exactly the legacy uncompressed 64x64 B8G8R8A8 file the generator writes.
bool IsValidIconDds(std::span<const uint8_t> data);

// Read <dir>/<SdkName>.dds for the binding's primary key and retain it for the
// process. Returns false, with one log line saying why, when the retail A icon
// stays.
bool Prepare(const std::filesystem::path& dir, std::string_view binding);

bool             TryGetPayload(Payload& payload);
std::string_view PreparedKey();
void             ResetForTests();

} // namespace rerevved::keyboard_icons
